import{_ as o,o as a,c as e,ag as r}from"./chunks/framework.B5ULsuav.js";const l=JSON.parse('{"title":"金刚经15分-信心不逆","description":"","frontmatter":{},"headers":[],"relativePath":"60-原文段落/金刚经15分-信心不逆.md","filePath":"60-原文段落/金刚经15分-信心不逆.md","lastUpdated":1778155802000}'),_={name:"60-原文段落/金刚经15分-信心不逆.md"};function s(n,t,p,u,c,i){return a(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="金刚经15分-信心不逆" tabindex="-1">金刚经15分-信心不逆 <a class="header-anchor" href="#金刚经15分-信心不逆" aria-label="Permalink to &quot;金刚经15分-信心不逆&quot;">​</a></h1><blockquote><p>来源：<a href="/liaokongjushi-wisdom/01-Raw-Sources/15了空居士讲《金刚经》-第十五分持经功德分20161209">15了空居士讲《金刚经》-第十五分持经功德分20161209</a> 切分日期：2026-05-06</p></blockquote><hr><p><strong>若复有人闻此经典，信心不逆，其福胜彼。</strong></p><p>如果有人听到佛祖前面讲的《金刚经》的内容。这里有个关键词是&quot;信心不逆&quot;。逆就是逆转，叛逆。就是他听了很相信，不会怀疑，不会退转，不会说：我不能相信了，不可能吧？信心不逆就是听了心生坚定的信心，佛祖讲的我都听得懂，我相信这就是这样的，没有一丝商量的余地，没有退心。</p><p>其福胜彼，他所得的福报胜过初日分、中日分、后日分以恒河沙等身布施，又布施了百千万亿劫那个人。其实这个就是关系到一个事情，就是他怎么去布施？假如他带有我相人相众生相寿者相去做，他布施多少还是有个数，也就是有限。能够听到《金刚经》然后信心不逆，信心不逆是什么？你就是信了吗？不是。他信了就会落到实处去为人处世。我们别以为信就是我相信就好了，你相信你有没有照做啊？只有你照那样去做，你才是真正的信啊。所以说解行并进，知行合一。古人这个真正的信，你相信了那你平时做事也要那么去做啊，假如你相信了，你不这么做，就是口是心非。所以一个人如果按照《金刚经》讲的道理去做，落到实处，这才是真正的信心不逆。如果你在这里听我讲，你就相信，等一下一下课，去做其他事情又忘记了，这个还是属于信心逆了。其福胜彼，他的福报就超过了以恒河沙生命布施了无量劫的那个人。这是什么意思呢，这个就是我们前面说的&quot;福德性&quot;和&quot;福德相&quot;这个范畴，也就是无限和有限。按照《金刚经》的经义去为人处世，你是跟整个法界不二了，不分彼此，法界有多少福德，你就有多少福德。着相去布施的，还是属于有限，你不管有多少总是有个穷尽。&quot;福德性&quot;就是法界有多少，你就和它相应了。</p><hr><p><strong>无我不等于没有</strong></p><p>无我是无私心妄想，一切都是般若智慧的流露——该吃饭吃饭，该做事做事，只是没有贪嗔痴慢疑。很多人以为&quot;无我&quot;就是人没有了，堕入空的邪见。无我不是人消失，是私心妄想消失了。一个人如果真的做到无我相、无人相、无众生相、无寿者相，这个人要说没有，他存在，要说他存在他没有种种私心妄想，所以这个人要说有，他确实站在我们面前，要说他没有，他真的没有私心。</p>',9)])])}const q=o(_,[["render",s]]);export{l as __pageData,q as default};
